Sure! Here's a simple JavaScript function that switches the order of adjectives in a sentence:

```javascript
function switchAdjectives(sentence) {
  const words = sentence.split(' ');
  const adjectives = [];

  for (let i = 0; i < words.length; i++) {
    if (words[i].match(/^(a|an|the)\s*(\w+)$/)) {
      adjectives.push(words[i]);
    }
  }

  if (adjectives.length > 1) {
    const firstAdjective = adjectives.shift();
    const lastAdjective = adjectives.pop();

    adjectives.unshift(lastAdjective);
    adjectives.push(firstAdjective);

    return adjectives.join(' ');
  } else {
    return sentence;
  }
}

const inputSentence = "Beautiful green trees are in the park";
const outputSentence = switchAdjectives(inputSentence);
console.log(outputSentence); // Output: Green beautiful trees are in the park
```

This function splits the sentence into an array of words, filters out the adjectives, and then swaps the positions of the first and last adjectives. Finally, it joins the adjectives back into a sentence and returns the result. If there are no adjectives in the sentence, it simply returns the original sentence unchanged.

