To blend different audio files and create a realistic experience of a summer day using Java, you can use libraries such as SoX or Java Sound API. Here's a simple example using Java Sound API:

```java
import java.applet.Applet;
import java.applet.AudioClip;
import java.awt.Color;
import java.io.File;
import javax.sound.sampled.*;
import javax.swing.*;

public class SummerDay extends Applet {
    private AudioClip birdClip, leafClip, cicadaClip, childClip;
    private Clip picnicClip, beachClip;

    public void init() {
        // Load audio clips
        birdClip = Applet.newAudioClip(getClass().getResource("bird.wav"));
        leafClip = Applet.newAudioClip(getClass().getResource("leaf.wav"));
        cicadaClip = Applet.newAudioClip(getClass().getResource("cicada.wav"));
        childClip = Applet.newAudioClip(getClass().getResource("child.wav"));
        picnicClip = Applet.newAudioClip(getClass().getResource("picnic.wav"));
        beachClip = Applet.newAudioClip(getClass().getResource("beach.wav"));

        // Create play buttons
        JButton picnicButton = new JButton("Play Picnic");
        JButton beachButton = new JButton("Play Beach");
        picnicButton.addActionListener(e -> playClip(picnicClip));
        beachButton.addActionListener(e -> playClip(beachClip));

        // Add play buttons to applet
        add(picnicButton);
        add(beachButton);
    }

    private void playClip(Clip clip) {
        try {
            clip.open();
            clip.start();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

