```go
package main

import (
	"fmt"
	"os"
	"reflect"
	"strings"

	"github.com/apache/avro/v2/schema"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: ./parse_struct <go_source_file> <struct_name>")
		os.Exit(1)
	}

	goSourceFile := os.Args[1]
	structName := os.Args[2]

	content, err := os.ReadFile(goSourceFile)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}

	tokens := strings.Split(string(content), "\n")

	for _, token := range tokens {
		if strings.HasPrefix(token, "type") && strings.Contains(token, structName) {
			typeDef := token[5:]
			typeDef = typeDef[:len(typeDef)-1] // Remove the trailing ';'

			fields := reflect.TypeOf(reflect.New(structName).Interface()).FieldByIndex([]int{0})

			schemaDef := schema.Schema{
				Name:    structName,
				Fields: make([]schema.Field, len(fields)),
			}

			for i, field := range fields {
				fieldName := field.Name
				fieldType := field.Type.String()

